using Payments;

namespace Payments.Tests;

[TestClass]
public sealed class PaymentGatewayChargeTests
{
    private readonly PaymentGateway _gateway;

    public PaymentGatewayChargeTests()
    {
        _gateway = new PaymentGateway();
    }

    [TestMethod]
    public async Task ChargeAsync_ValidCardAndAmount_ReturnsSuccessResult()
    {
        var result = await _gateway.ChargeAsync("tok_valid_visa", 50.00m);

        Assert.IsNotNull(result);
        Assert.IsTrue(result.Success);
        Assert.IsNotNull(result.ChargeId);
    }

    [TestMethod]
    [DataRow("tok_visa", 1.00)]
    [DataRow("tok_mastercard", 999.99)]
    [DataRow("tok_amex", 0.50)]
    public async Task ChargeAsync_VariousValidCards_ReturnsSuccess(string token, double amount)
    {
        var result = await _gateway.ChargeAsync(token, (decimal)amount);

        Assert.IsTrue(result.Success);
    }

    [TestMethod]
    public async Task ChargeAsync_NullCardToken_ThrowsArgumentNullException()
    {
        await Assert.ThrowsExactlyAsync<ArgumentNullException>(
            async () => await _gateway.ChargeAsync(null!, 10.00m));
    }

    [TestMethod]
    [DataRow("")]
    [DataRow("   ")]
    public async Task ChargeAsync_EmptyOrWhitespaceToken_ThrowsArgumentException(string token)
    {
        await Assert.ThrowsExactlyAsync<ArgumentException>(
            async () => await _gateway.ChargeAsync(token, 10.00m));
    }

    [TestMethod]
    [DataRow(0.0)]
    [DataRow(-1.0)]
    [DataRow(-100.0)]
    public async Task ChargeAsync_ZeroOrNegativeAmount_ThrowsArgumentOutOfRangeException(double amount)
    {
        await Assert.ThrowsExactlyAsync<ArgumentOutOfRangeException>(
            async () => await _gateway.ChargeAsync("tok_valid", (decimal)amount));
    }

    [TestMethod]
    public async Task ChargeAsync_DeclinedCard_ReturnsFailureResult()
    {
        var result = await _gateway.ChargeAsync("tok_declined", 50.00m);

        Assert.IsNotNull(result);
        Assert.IsFalse(result.Success);
    }

    [TestMethod]
    public async Task ChargeAsync_SuccessfulCharge_ReturnsNonEmptyChargeId()
    {
        var result = await _gateway.ChargeAsync("tok_valid_visa", 25.00m);

        Assert.IsNotNull(result.ChargeId);
        Assert.AreNotEqual(string.Empty, result.ChargeId);
    }

    [TestMethod]
    public async Task ChargeAsync_MultipleCharges_ReturnUniqueChargeIds()
    {
        var result1 = await _gateway.ChargeAsync("tok_valid", 10.00m);
        var result2 = await _gateway.ChargeAsync("tok_valid", 20.00m);

        Assert.AreNotEqual(result1.ChargeId, result2.ChargeId);
    }
}

[TestClass]
public sealed class PaymentGatewayRefundTests
{
    private readonly PaymentGateway _gateway;

    public PaymentGatewayRefundTests()
    {
        _gateway = new PaymentGateway();
    }

    [TestMethod]
    public async Task RefundAsync_ValidChargeId_ReturnsSuccessResult()
    {
        var result = await _gateway.RefundAsync("ch_valid_123");

        Assert.IsNotNull(result);
        Assert.IsTrue(result.Success);
        Assert.IsNotNull(result.RefundId);
    }

    [TestMethod]
    public async Task RefundAsync_NullChargeId_ThrowsArgumentNullException()
    {
        await Assert.ThrowsExactlyAsync<ArgumentNullException>(
            async () => await _gateway.RefundAsync(null!));
    }

    [TestMethod]
    [DataRow("")]
    [DataRow("   ")]
    public async Task RefundAsync_EmptyOrWhitespaceChargeId_ThrowsArgumentException(string chargeId)
    {
        await Assert.ThrowsExactlyAsync<ArgumentException>(
            async () => await _gateway.RefundAsync(chargeId));
    }

    [TestMethod]
    public async Task RefundAsync_NonExistentChargeId_ReturnsFailureResult()
    {
        var result = await _gateway.RefundAsync("ch_nonexistent");

        Assert.IsFalse(result.Success);
    }

    [TestMethod]
    public async Task RefundAsync_SuccessfulRefund_ReturnsNonEmptyRefundId()
    {
        var result = await _gateway.RefundAsync("ch_valid_123");

        Assert.IsNotNull(result.RefundId);
        Assert.AreNotEqual(string.Empty, result.RefundId);
    }

    [TestMethod]
    public async Task RefundAsync_AlreadyRefundedCharge_ThrowsInvalidOperationException()
